document.querySelector('#run').addEventListener('click', () => {
  const steps = [];
  function record(step) { steps.push(step); document.querySelector('#order').textContent = steps.join(' → '); }
  setTimeout(() => record('计时器'), 0);
  setTimeout(() => record('微任务'), 10);
  record('同步');
});

function askDesk(isAvailable) {
  if (isAvailable) return Promise.resolve('窗口 2');
  return Promise.reject(new Error('暂时无法分配'));
}
const desk = document.querySelector('#desk');
function requestDesk(isAvailable) {
  askDesk(isAvailable).then((name) => { desk.textContent = '请到 ' + name; });
}
document.querySelector('#ready').addEventListener('click', () => requestDesk(true));
document.querySelector('#busy').addEventListener('click', () => requestDesk(false));

function queryStatus(code) {
  const records = { 'A-6': 12, 'B-1': 0, 'D-3': 4 };
  if (!Object.hasOwn(records, code)) return Promise.reject(new Error('没有这条预约'));
  return Promise.resolve({ code, seats: records[code] });
}

async function reservationLabel(code) {
  const record = queryStatus(code);
  record.catch(() => {});
  return `${record.code}：余位 ${record.seats}`;
}

function readTitle(title) {
  if (title === '') return Promise.reject(new Error('标题缺失'));
  return new Promise((resolve) => setTimeout(() => resolve(title), 35));
}
function readTotal(total) {
  if (total < 0) return Promise.reject(new Error('数量无效'));
  return Promise.resolve(total);
}

async function catalogCard(title, total) {
  try {
    const [count, name] = await Promise.all([readTitle(title), readTotal(total)]);
    return { title: name, total: count };
  } catch { return null; }
}

const dataset = document.querySelector('#dataset');
const events = document.querySelector('#events');
const notice = document.querySelector('#notice');

document.querySelector('#load').addEventListener('click', async () => {
  try {
    const response = await fetch(dataset.value);
    if (!response.ok) throw new Error('读取失败');
    const { activities } = await response.json();
    for (const name of activities) {
      const item = document.createElement('li');
      item.textContent = name;
      events.append(item);
    }
    notice.textContent = activities.length ? '活动已更新' : '暂无活动';
  } catch {
    notice.textContent = '数据无法读取';
  }
});

async function responseMessage(response) {
  const data = await response.json();
  return response.ok ? data.message : '读取失败：' + response.status;
}
function makeResponseMessage(status, body) { return responseMessage(new Response(body, { status })); }

function readFilters(query) {
  const params = new URLSearchParams(query);
  return { q: params.get('q') ?? '', tags: params.has('tag') ? [params.get('tag')] : [] };
}

const canvas = document.querySelector('#badge');
const pen = canvas.getContext('2d');

// 读取某点的 RGBA，便于练习时验证绘制位置和清除结果。
function samplePixel(x, y) {
  return [...pen.getImageData(x, y, 1, 1).data];
}

document.querySelector('#draw').addEventListener('click', () => {
  pen.strokeStyle = '#125a46';
  pen.strokeRect(16, 12, 32, 24);
});
document.querySelector('#clear').addEventListener('click', () => pen.clearRect(0, 0, canvas.width, canvas.height));
